<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Verifications</div><div class="page-header"><div><div class="eyebrow">TRUST & SAFETY</div><h1>Verification requests</h1><p>Review identity documents submitted by marketplace users.</p></div></div><section class="verification-summary"><div><strong>{{ requests.length }}</strong><span>Total submissions</span></div><div class="pending-card"><strong>{{ pending }}</strong><span>Awaiting review</span></div><div><strong>{{ approved }}</strong><span>Approved</span></div><div><strong>{{ rejected }}</strong><span>Rejected</span></div></section><section class="order-tabs verification-tabs"><button v-for="tab in tabs" :key="tab" :class="{active:filter===tab}" @click="filter=tab">{{ label(tab) }} <span>{{ count(tab) }}</span></button></section><section class="listing-panel"><div class="listing-toolbar"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search user, phone or email…"/></div><span>{{ filtered.length }} requests</span></div><div v-if="filtered.length" class="verification-list"><div class="verification-row verification-head"><span>Applicant</span><span>Submitted</span><span>Documents</span><span>Status</span><span>Reviewed by</span><span></span></div><Link v-for="item in filtered" :key="item.id" :href="route('verification-requests.show',item.id)" class="verification-row"><div class="user-cell"><span class="user-avatar"><img v-if="item.user?.image" :src="item.user.image"/><b v-else>{{ initial(item.user?.name) }}</b></span><div><strong>{{ item.user?.name||'Deleted user' }}</strong><small>{{ item.user?.phone||item.user?.email||`Request #${item.id}` }}</small></div></div><span>{{ formatDate(item.created_at) }}</span><div class="document-thumbs"><img :src="item.front_image"/><img :src="item.back_image"/></div><span class="verification request-status" :class="item.status">{{ label(item.status) }}</span><span>{{ item.reviewer?.name||'—' }}</span><b>›</b></Link></div><div v-else class="empty-state"><div>✓</div><strong>No requests found</strong><p>{{ filter==='pending'?'The review queue is clear.':'Try another filter or search.' }}</p></div></section></Layout></template>
<script setup>import{ref,computed,onMounted}from'vue';import{usePage}from'@inertiajs/vue3';import{useToast}from'vue-toastification';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({requests:{type:Array,default:()=>[]}}),query=ref(''),filter=ref('pending'),tabs=['all','pending','approved','rejected','superseded'];const count=s=>s==='all'?props.requests.length:props.requests.filter(r=>r.status===s).length,pending=computed(()=>count('pending')),approved=computed(()=>count('approved')),rejected=computed(()=>count('rejected'));const filtered=computed(()=>{const q=query.value.toLowerCase();return props.requests.filter(r=>(filter.value==='all'||r.status===filter.value)&&[r.user?.name,r.user?.phone,r.user?.email].some(x=>x?.toLowerCase().includes(q)))});const label=s=>s.charAt(0).toUpperCase()+s.slice(1),initial=n=>(n||'?').charAt(0).toUpperCase(),formatDate=d=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d));const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
